SINA_SMART["physio1-respiratory"] = {"lecture":"physio1-respiratory","title":"Introduction to the respiratory system","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"physio1-respiratory:e0","text":"Lung roles: gas exchange, metabolism (angiotensin), blood reservoir.","topic":"Roles of the lung and gas exchange","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-respiratory:e1","text":"Exchange of O₂/CO₂ by passive diffusion across the alveolar-capillary membrane.","topic":"Roles of the lung and gas exchange","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-respiratory:e2","text":"Fick: ∝ area, solubility, ΔP; ∝ 1/thickness, 1/√MW.","topic":"Roles of the lung and gas exchange","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-respiratory:e3","text":"PIO₂ = (760 − 47) × 0.21 ≈ 150 mmHg.","topic":"Partial pressures","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-respiratory:e4","text":"PAO₂ ≈ 100, PACO₂ ≈ 40; PvO₂ ≈ 40, PvCO₂ ≈ 45 mmHg.","topic":"Partial pressures","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-respiratory:e5","text":"PaCO₂ ≈ PACO₂.","topic":"Partial pressures","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-respiratory:e7","text":"VT = VD + VA (500 = 150 + 350 mL).","topic":"Partial pressures","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-respiratory:e6","text":"Conducting zone (dead space) vs respiratory zone (exchange).","topic":"Conducting and respiratory zones","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-respiratory:e8","text":"VE = 7.5 L/min; VA = 5.25 L/min; Q = 4.9 L/min; VA/Q ≈ 1.","topic":"Ventilation and perfusion","sec":3,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"1341tbd":"a","6167a1":"a","1eeypfc":"a","1cajxjv":"a","10e4cz4":"a","isuzkg":"a","iczgnx":"a","q1y4bw":"a","117tg67":"a","1fqiql7":"a","kvdhp8":"a","198wmyp":"a","i7hlo8":"a","1gi7qo6":"a","y20u90":"x"},"mapCounts":{"verified":0,"auto":14,"ambiguous":0,"missing":1},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"physio1-respiratory:e0":{"s":0,"u":["Lung roles: gas exchange, metabolism (angiotensin), blood reservoir.","The lung has three roles: gas exchange , metabolism (activation or inactivation of molecules, e.g. converting angiotensin I to II) and a blood reservoir .","Pulmonary gas exchange concerns O₂ and CO₂ , between air (the O₂ provider and CO₂ remover) and blood , across the alveolar-capillary membrane , by passive diffusion ."],"dp":[]},"physio1-respiratory:e1":{"s":0,"u":["Exchange of O₂/CO₂ by passive diffusion across the alveolar-capillary membrane.","Pulmonary gas exchange concerns O₂ and CO₂ , between air (the O₂ provider and CO₂ remover) and blood , across the alveolar-capillary membrane , by passive diffusion ."],"dp":[]},"physio1-respiratory:e2":{"s":0,"u":["Fick: ∝ area, solubility, ΔP; ∝ 1/thickness, 1/√MW.","Fick's law : the transfer rate is proportional to the gas's solubility , the surface area and the partial pressure difference , and inversely proportional to thickness and molecular weight."],"dp":[]},"physio1-respiratory:e3":{"s":1,"u":["PIO₂ = (760 − 47) × 0.21 ≈ 150 mmHg.","Inspired O₂ : PIO₂ = (P atm − P H₂O ) × FIO₂ = (760 − 47) × 0.21 ≈ 150 mmHg .","Worked examples from the lecture: at 5,500 m (P atm ≈ 360 mmHg) PIO₂ ≈ (360 − 47) × 0.21 ≈ 65 mmHg ; on Everest (P atm ≈ 250 mmHg) PIO₂ ≈ 42 mmHg ; a patient with PaCO₂ 50 mmHg has an alveolar PCO₂ of about 50 mmHg ."],"dp":[]},"physio1-respiratory:e4":{"s":1,"u":["PAO₂ ≈ 100, PACO₂ ≈ 40; PvO₂ ≈ 40, PvCO₂ ≈ 45 mmHg.","Alveolar : PAO₂ ≈ 100 , PACO₂ ≈ 40 mmHg (inspired CO₂ ≈ 0).","Mixed venous : PvO₂ ≈ 40 , PvCO₂ ≈ 45 mmHg ."],"dp":[]},"physio1-respiratory:e5":{"s":1,"u":["PaCO₂ ≈ PACO₂.","Gradients drive O₂ from alveoli to blood and CO₂ from blood to alveoli; because CO₂ equilibrates fully, arterial PaCO₂ ≈ alveolar PACO₂ .","Alveolar : PAO₂ ≈ 100 , PACO₂ ≈ 40 mmHg (inspired CO₂ ≈ 0)."],"dp":[]},"physio1-respiratory:e7":{"s":1,"u":["VT = VD + VA (500 = 150 + 350 mL).","Inspired O₂ : PIO₂ = (P atm − P H₂O ) × FIO₂ = (760 − 47) × 0.21 ≈ 150 mmHg ."],"dp":[]},"physio1-respiratory:e6":{"s":2,"u":["Conducting zone (dead space) vs respiratory zone (exchange).","The respiratory zone (respiratory bronchioles, alveolar ducts, sacs, alveoli) is where exchange occurs.","The conducting zone (nose to terminal bronchioles) transports, warms, humidifies, filters and cleans the air (mucus traps particles, cilia move it out) and produces voice; it does not exchange gas: this is the anatomical dead space ."],"dp":[]},"physio1-respiratory:e8":{"s":3,"u":["VE = 7.5 L/min; VA = 5.25 L/min; Q = 4.9 L/min; VA/Q ≈ 1.","Multiplying by the respiratory rate (15/min): minute ventilation VE = 7.5 L/min , of which alveolar ventilation VA = 5.25 L/min takes part in exchange.","Pulmonary blood flow equals cardiac output : 70 mL × 70/min ≈ 4.9 L/min ."],"dp":[{"h":"Why shallow fast breathing is inefficient","t":"The anatomical dead space (about 150 mL) is ventilated on every breath whatever the tidal volume. Breathing 500 mL 15 times a minute gives 5.25 L/min of alveolar ventilation. Breathing 250 mL 30 times a minute gives the same minute ventilation (7.5 L/min), but only 100 mL per breath reaches the alveoli: 3 L/min. That is why a patient taking rapid shallow breaths (pain, fatigue, drugs) can retain CO₂ even though the breathing looks busy, and why deep, slower breaths are more efficient. Source: the lecture's VT = VD + VA example."}]}},"meta":{"1341tbd":{"a":"recall","vg":"physio1-respiratory:e7/recall/1"},"6167a1":{"a":"recall","vg":"physio1-respiratory:e3/recall/1"},"1eeypfc":{"a":"recall","vg":"physio1-respiratory:e4/recall/1"},"1cajxjv":{"a":"recall","vg":"physio1-respiratory:e4/recall/1"},"10e4cz4":{"a":"recall","vg":"physio1-respiratory:e3/recall/2"},"isuzkg":{"a":"recall","vg":"physio1-respiratory:e3/recall/2"},"iczgnx":{"a":"application","vg":"physio1-respiratory:e3/application/1"},"q1y4bw":{"a":"recall","vg":"physio1-respiratory:e2/recall/1"},"117tg67":{"a":"recall","vg":"physio1-respiratory:e6/recall/1"},"1fqiql7":{"a":"recall","vg":"physio1-respiratory:e6/recall/2"},"kvdhp8":{"a":"recall","vg":"physio1-respiratory:e7/recall/2"},"198wmyp":{"a":"recall","vg":"physio1-respiratory:e8/recall/1"},"i7hlo8":{"a":"recall","vg":"physio1-respiratory:e8/recall/1"},"1gi7qo6":{"a":"recall","vg":"physio1-respiratory:e8/recall/2"}},"explRev":"4cc841e3741d"};
